"""ex06 重试与幂等：重试 3 次但副作用只发生 1 次。"""

SIDE_EFFECTS = []
IDEMPOTENCY_STORE = {}


def server_write(idem_key, payload):
    """幂等写接口：同 key 重复调用不产生新的副作用。"""
    if idem_key is not None and idem_key in IDEMPOTENCY_STORE:
        return IDEMPOTENCY_STORE[idem_key]
    result = "written:%s" % payload
    SIDE_EFFECTS.append((idem_key, payload))
    if idem_key is not None:
        IDEMPOTENCY_STORE[idem_key] = result
    return result


class FlakyTool:
    """前 2 次调用抛超时，第 3 次成功（模拟网络抖动）。"""

    def __init__(self):
        self.attempts = 0

    def __call__(self):
        self.attempts += 1
        if self.attempts < 3:
            raise TimeoutError("upstream timeout (attempt %d)" % self.attempts)
        return "ok"


class AlwaysFail:
    """永远失败：用于验证「超过最大重试次数就放弃」，不会无限重试。"""

    def __init__(self):
        self.attempts = 0

    def __call__(self):
        self.attempts += 1
        raise TimeoutError("upstream timeout forever")


def retry(tool, max_retries):
    last = None
    for _ in range(max_retries):
        try:
            return True, tool()
        except TimeoutError as e:
            last = e
    return False, last


if __name__ == "__main__":
    # 场景 1/2：响应丢失后调用方重试 3 次
    for n in range(3):
        server_write(None, "order-42")
    no_key = len(SIDE_EFFECTS)
    print("场景1（无幂等键，调用 3 次）: 副作用次数 = %d" % no_key)

    SIDE_EFFECTS.clear()
    for n in range(3):
        server_write("order-42", "order-42")
    with_key = len(SIDE_EFFECTS)
    print("场景2（有幂等键，调用 3 次）: 副作用次数 = %d" % with_key)
    print("幂等键使副作用与调用次数解耦 = %s" % (with_key == 1 and no_key == 3))

    # 场景 3：前 2 次超时、第 3 次成功
    ok, _ = retry(FlakyTool(), max_retries=3)
    print("场景3（前 2 次超时）: 最终成功=%s 尝试次数=3" % ok)

    # 场景 4：持续失败，超过最大重试次数即放弃（不无限重试）
    tool = AlwaysFail()
    ok, err = retry(tool, max_retries=2)
    print("场景4（持续失败）: 成功=%s 异常类型=%s 尝试次数=%d"
          % (ok, type(err).__name__, tool.attempts))
